export type NomeDeLogoPortal = keyof typeof LOGOS;

export function LogoPortal({
  nome,
  tamanho = 28,
  ...resto
}: { nome: NomeDeLogoPortal; tamanho?: number } & Omit<SVGProps<SVGSVGElement>, 'name'>) {
  return (
    <svg
      width={tamanho}
      height={tamanho}
      viewBox="0 0 80 80"
      fill="none"
      aria-hidden="true"
      focusable="false"
      {...resto}
    >
      {LOGOS[nome]}
    </svg>
  );
}

export function IconePortal({
  nome,
  tamanho = 24,
  ...resto
}: { nome: NomeDeIconePortal; tamanho?: number } & Omit<SVGProps<SVGSVGElement>, 'name'>) {
  const desenho = DESENHOS[nome];
  return (
    <svg
      width={tamanho}
      height={tamanho}
      viewBox="0 0 24 24"
      fill="currentColor"
      aria-hidden="true"
      focusable="false"
      {...resto}
    >
      {desenho.partes.map((d) => (
        <path key={d.slice(0, 24)} d={d} fillRule={desenho.parOuImpar ? 'evenodd' : undefined} />
      ))}
    </svg>
  );
}

